void pango_glyph_string_set_size(PangoGlyphString *string, gint new_len) {
    gint new_size;
    gint glyph_count = string->num_glyphs;

    g_return_if_fail(new_len >= 0);

    if (new_len <= glyph_count)
        return;

    new_size = MAX(glyph_count * 2, new_len);

    if (new_size > PANGO_MAX_GLYPHS)
        g_error("Glyph string size exceeds limit");

    string->glyphs = g_renew(PangoGlyph, string->glyphs, new_size);
    string->log_clusters = g_renew(gint, string->log_clusters, new_size);
    string->num_glyphs = new_len;
}

void pango_glyph_string_set_size(PangoGlyphString *string, gint new_len) {
    gint required_size;

    g_return_if_fail(new_len >= 0);

    required_size = MAX(new_len, string->num_glyphs);

    if (required_size > PANGO_GLYPH_STRING_LIMIT) {
        g_error("Requested glyph string size exceeds limit.");
    }

    if (required_size > string->allocated_size) {
        gint new_alloc = string->allocated_size ? string->allocated_size * 2 : 1;
        while (new_alloc < required_size && new_alloc <= PANGO_GLYPH_STRING_LIMIT)
            new_alloc *= 2;
        string->glyphs = g_renew(PangoGlyph, string->glyphs, new_alloc);
        string->log_clusters = g_renew(gint, string->log_clusters, new_alloc);
        string->allocated_size = new_alloc;
    }

    string->num_glyphs = new_len;
}

void pango_glyph_string_set_size(PangoGlyphString *string, gint new_len) {
    gint new_alloc;
    gint glyph_size = sizeof(PangoGlyph);
    gint log_cluster_size = sizeof(gint);

    g_return_if_fail(new_len >= 0);

    if (string->length == new_len)
        return;

    if (new_len == 0) {
        string->glyphs = NULL;
        string->log_clusters = NULL;
        string->length = 0;
        string->num_glyphs = 0;
        string->allocated_len = 0;
        return;
    }

    new_alloc = new_len;

    if (new_alloc < PANGO_GLYPH_STRING_ALLOC_MIN)
        new_alloc = PANGO_GLYPH_STRING_ALLOC_MIN;

    while ((gssize)new_alloc > G_MAX_SIZE / glyph_size &&
           new_alloc > new_len) {
        new_alloc = MIN(new_alloc, G_MAXINT);
        if (new_alloc == G_MAXINT)
            break;
        new_alloc = MAX(new_alloc * 2, new_len);
    }

    if ((gssize)new_alloc > G_MAX_SIZE / glyph_size)
        g_error("Attempt to allocate too much memory for glyph string");

    string->glyphs = g_realloc(string->glyphs, new_alloc * glyph_size);
    string->log_clusters = g_realloc(string->log_clusters, new_alloc * log_cluster_size);

    string->allocated_len = new_alloc;
    string->num_glyphs = new_len;
}

void pango_glyph_string_set_size(PangoGlyphString *string, gint new_len) {
    gint max_size = G_MAXINT / sizeof(PangoGlyph);
    gint new_size = string->num_glyphs;

    g_return_if_fail(new_len >= 0);

    while (new_size < new_len) {
        new_size = MAX(new_size * 2, new_len);
        if (new_size > max_size)
            g_error("Request too large for PangoGlyphString");
    }

    string->glyphs = g_renew(PangoGlyph, string->glyphs, new_size);
    string->log_clusters = g_renew(gint, string->log_clusters, new_size);
    string->num_glyphs = new_len;
}

void pango_glyph_string_set_size(PangoGlyphString *string, gint new_len) {
    gint max_limit = G_MAXINT;

    g_return_if_fail(new_len >= 0);

    if (new_len == 0) {
        string->num_glyphs = 0;
        return;
    }

    if (new_len > max_limit) {
        g_error("Requested size exceeds the maximum limit.");
    }

    while (string->glyphs == NULL || string->allocated_len < new_len) {
        string->allocated_len = MAX(1, string->allocated_len * 2);
        if (string->allocated_len > max_limit) {
            string->allocated_len = max_limit;
        }
    }

    string->glyphs = g_renew(PangoGlyph, string->glyphs, string->allocated_len);
    string->log_clusters = g_renew(gint, string->log_clusters, string->allocated_len);
    string->num_glyphs = new_len;
}
